import{_ as s,E as n,h as d,c as l,b as e,f as a,H as i,w as c,a4 as p}from"./chunks/framework.B_fYP6Of.js";const y=JSON.parse('{"title":"Portable knowledge and identity","description":"Distinguish an immutable source, a mention, an entity and a qualified claim, then trace how review and portable export retain their history.","frontmatter":{"title":"Portable knowledge and identity","description":"Distinguish an immutable source, a mention, an entity and a qualified claim, then trace how review and portable export retain their history.","teaser":"Two people can share a name. Two witnesses can describe one event. The library needs a way to connect records while preserving what each source actually said."},"headers":[],"relativePath":"project/knowledge.md","filePath":"project/knowledge.md"}'),h={name:"project/knowledge.md"};function u(m,t,b,f,g,v){const o=n("LabArticleHeader"),r=n("LabScroll");return d(),l("div",null,[t[1]||(t[1]=e("h1",{id:"portable-knowledge-and-identity",tabindex:"-1"},[a("Portable knowledge and identity "),e("a",{class:"header-anchor",href:"#portable-knowledge-and-identity","aria-label":'Permalink to "Portable knowledge and identity"'},"​")],-1)),i(o),t[2]||(t[2]=e("p",null,"Consider two documents that both mention “A. Lee.” The matching text gives the system two mentions. Deciding they refer to the same person requires a separate decision, with candidate identities, evidence and a recorded reason. If a later source changes that judgment, the original passages must still be available.",-1)),t[3]||(t[3]=e("p",null,[e("strong",null,"Proposed format and invariants."),a(" The historical graph supplies candidate/review patterns, not a finished research ontology. See H-03 in the "),e("a",{href:"./../reuse/source-audit"},"source audit"),a(".")],-1)),t[4]||(t[4]=e("p",null,"In a fictional harbor notebook, A. Lee writes, “The light stayed near the pier.” A worker proposes linking the signature to Alex Lee, a dock worker. A later signed page identifies the writer as Avery Lee, a dispatcher. A reviewer records the new evidence and corrects the assignment in the next revision. Both revisions still point to the original words. A reader can inspect why the identification changed and who approved it.",-1)),t[5]||(t[5]=e("h2",{id:"records-and-their-identities",tabindex:"-1"},[a("Records and their identities "),e("a",{class:"header-anchor",href:"#records-and-their-identities","aria-label":'Permalink to "Records and their identities"'},"​")],-1)),i(r,{kind:"table",label:"table for Records and their identities"},{default:c(()=>[...t[0]||(t[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Record"),e("th",{scope:"col"},"Identity and invariant")])]),e("tbody",null,[e("tr",null,[e("td",null,"Artifact"),e("td",null,"Exact immutable bytes and cryptographic digest; metadata fingerprints are separate")]),e("tr",null,[e("td",null,"Acquisition/source version"),e("td",null,"Where/when/how material was acquired, rights, source ID/version and artifact link")]),e("tr",null,[e("td",null,"Mention"),e("td",null,"A precise reference in an immutable text/media artifact")]),e("tr",null,[e("td",null,"Canonical entity"),e("td",null,"Stable opaque ID independent of display name, evidence count or extraction model")]),e("tr",null,[e("td",null,"Qualified claim"),e("td",null,"Subject, controlled predicate, object/value, polarity, modality and time qualifiers")]),e("tr",null,[e("td",null,"Assertion/evidence"),e("td",null,"A source's support, contradiction or reported statement about a claim")]),e("tr",null,[e("td",null,"Resolution/review decision"),e("td",null,"Actor/method, candidate set, evidence, reason and base/published revision")])])],-1)])]),_:1}),t[6]||(t[6]=p(`<p>Identical bytes may have distinct acquisition records. Repeated imports may be deduplicated without counting copied articles as independent corroboration. A single relationship projection can represent several assertions without erasing their differences.</p><h2 id="resolution-is-not-name-deduplication" tabindex="-1">Resolution is not name deduplication <a class="header-anchor" href="#resolution-is-not-name-deduplication" aria-label="Permalink to &quot;Resolution is not name deduplication&quot;">​</a></h2><p>Name normalization and embeddings generate candidates. They do not authorize identity changes. Aliases are many-to-many and scoped by language, type, time or context. External identifiers are unique only within their declared authority and entity scope.</p><p>Example: two people named Alex Lee remain two entities. Two names for one incident can resolve to one incident. A vessel named in a report must not merge with the incident. Persist negative matches and unresolved decisions so later extraction does not repeat a known false match.</p><p>Canonical IDs survive new evidence. Candidate hashes may change with provenance; that is a new proposal, not necessarily a new person. Merges/splits create versioned decisions and assignments; old mentions and published revisions remain inspectable.</p><h2 id="evidence-locations" tabindex="-1">Evidence locations <a class="header-anchor" href="#evidence-locations" aria-label="Permalink to &quot;Evidence locations&quot;">​</a></h2><p>A text span identifies the immutable extracted-text artifact, parser/version and a defined offset convention such as a half-open UTF-8 byte range. The text artifact links back to the original document; extracted offsets must not pretend to be original PDF byte positions.</p><p>Media evidence identifies the source hash, track and interval in an explicit rational time base. Preserve extraction receipts and selected frames where needed. Narration, visual detection and calibrated measurement are different assertion kinds.</p><h2 id="confidence-and-disagreement" tabindex="-1">Confidence and disagreement <a class="header-anchor" href="#confidence-and-disagreement" aria-label="Permalink to &quot;Confidence and disagreement&quot;">​</a></h2><p>One number cannot answer three different questions: how clearly the words were recorded, how likely the speaker was a particular person, and how well the speaker supported a claim. Keep each assessment attached to the decision it describes so a reviewer knows which one to revisit.</p><p>Separate extraction quality, identity score, source quality, dependence/corroboration and claim assessment. A fixed heuristic score is not a probability of truth. Record the scoring method/version and its calibration evidence when available.</p><p>Use reviewable assessments such as reported, disputed or unresolved. Preserve both sides of a contradiction. The system can know exactly who reported a statement without asserting that the statement is established fact.</p><h2 id="atomic-publication" tabindex="-1">Atomic publication <a class="header-anchor" href="#atomic-publication" aria-label="Permalink to &quot;Atomic publication&quot;">​</a></h2><p>An approved proposal is immutable and digest-bound. The publish command checks authenticated review authority, expected base revision, scope/rights, evidence existence and integrity, all endpoints and ontology constraints before committing canonical changes, review receipt, revision and publication event together.</p><p>A worker success or a CLI approval flag alone cannot publish truth. The <a href="./../engineering/examples#atomic-publication">transaction lab</a> demonstrates a limited rollback/digest/revision contract; it does not implement the full publisher.</p><h2 id="portable-package" tabindex="-1">Portable package <a class="header-anchor" href="#portable-package" aria-label="Permalink to &quot;Portable package&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research.knowledge/</span></span>
<span class="line"><span>  manifest.json</span></span>
<span class="line"><span>  library.sqlite</span></span>
<span class="line"><span>  objects/sha256/...</span></span>
<span class="line"><span>  workflows/...</span></span>
<span class="line"><span>  models/manifests/...</span></span></code></pre></div><p>The manifest records format version, revision, hashes and required features. Credentials, executable auto-start behavior, machine paths and GPU handles are not portable evidence. Model weights are included only under explicit rights and size policy; model manifests are not proof that a model exists on the receiving machine.</p><p>Embedding-space identity includes immutable model and tokenizer/preprocessing identity, dimensions, normalization and similarity metric. Same dimensions do not establish interoperability. Preserve vectors when their compatible query encoder is missing and expose the narrower available search capability.</p><h2 id="export-import-and-retention" tabindex="-1">Export, import and retention <a class="header-anchor" href="#export-import-and-retention" aria-label="Permalink to &quot;Export, import and retention&quot;">​</a></h2><p>Use a supported consistent SQLite snapshot operation and include every referenced immutable object. Do not copy only a live database&#39;s main file and ignore its WAL. Validate package schema and object hashes before activation. <a href="https://sqlite.org/backup.html" target="_blank" rel="noreferrer">SQLite backup API</a>, <a href="https://sqlite.org/wal.html" target="_blank" rel="noreferrer">WAL</a>, <a href="https://sqlite.org/onefile.html" target="_blank" rel="noreferrer">file portability</a>.</p><p>A public export is newly constructed from approved records and objects, including safe search indexes. It is not a whole authoring database with draft rows hidden in the interface. Check bytes, manifests and indexes for private content; deleted rows or rebuilt UI filters do not prove removal from a copied file.</p><p>Import never executes bundled code or resumes external actions automatically. Keep old revisions/artifacts while answer citations require them, according to an explicit retention policy. Synchronizing concurrent authoring copies is a later reconciliation feature, not a filesystem-copy operation.</p>`,23))])}const k=s(h,[["render",u]]);export{y as __pageData,k as default};
